const candidate = $('Get Candidate Application').first().json;
const job = $('Get Job Requirements').first().json;

const isBlank = (value) =>
  value === undefined ||
  value === null ||
  String(value).trim() === '';

const errors = [];

// Verify the candidate's identity and job reference.
const candidateRequiredFields = [
  'Application ID',
  'Job ID'
];

for (const field of candidateRequiredFields) {
  if (isBlank(candidate[field])) {
    errors.push(`Candidate field is missing: ${field}`);
  }
}

// Verify the job record.
const jobRequiredFields = [
  'Job ID',
  'Required Skills',
  'Experience Required',
  'Education Required',
  'Job Description'
];

for (const field of jobRequiredFields) {
  if (isBlank(job[field])) {
    errors.push(`Job field is missing: ${field}`);
  }
}

// Ensure the candidate and job records correspond.
const candidateJobId = String(candidate['Job ID'] ?? '').trim();
const jobJobId = String(job['Job ID'] ?? '').trim();

if (
  candidateJobId &&
  jobJobId &&
  candidateJobId.toUpperCase() !== jobJobId.toUpperCase()
) {
  errors.push('Candidate Job ID does not match the retrieved job.');
}

// Only open jobs are eligible for matching.
const jobStatus = String(job['Job Status'] ?? '')
  .trim()
  .toLowerCase();

if (jobStatus !== 'open') {
  errors.push('Job is not Open. Matching must not proceed.');
}

// Missing candidate profile information is flagged separately.
// It should lead to manual review, not an automatic rejection.
const missingProfileFields = [
  'Parsed Skills',
  'Education',
  'Experience'
].filter(field => isBlank(candidate[field]));

return [
  {
    json: {
      validationPassed: errors.length === 0,
      validationErrors: errors,
      candidateProfileSufficient: missingProfileFields.length === 0,
      missingProfileFields,
      candidate,
      job
    }
  }
];

const data = $input.first().json;

const candidate = data.candidate;
const job = data.job;

function cleanText(value) {
  if (value === undefined || value === null) {
    return '';
  }

  if (Array.isArray(value)) {
    return value.map(item => String(item)).join(', ');
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value).trim();
}

// AI processing is allowed only when both records
// are valid and the candidate profile is sufficiently complete.
const readyForAI =
  data.validationPassed === true &&
  data.candidateProfileSufficient === true;

const output = {
  readyForAI,
  candidateApplicationId: candidate['Application ID'],
  validationErrors: data.validationErrors || [],
  missingProfileFields: data.missingProfileFields || [],
  routingReason: readyForAI
    ? 'Candidate and job data passed validation.'
    : 'AI matching skipped. Validation or candidate information is insufficient.'
};

if (readyForAI) {
  output.matchingInput = {
    candidate: {
      skills: cleanText(candidate['Parsed Skills']),
      education: cleanText(candidate['Education']),
      experience: cleanText(candidate['Experience'])
    },
    job: {
      requiredSkills: cleanText(job['Required Skills']),
      preferredSkills: cleanText(job['Preferred Skills']),
      experienceRequired: cleanText(job['Experience Required']),
      educationRequired: cleanText(job['Education Required']),
      jobDescription: cleanText(job['Job Description'])
    }
  };
}

return [{ json: output }];

const data = $input.first().json;

const reasons = [];

if (Array.isArray(data.validationErrors)) {
  reasons.push(...data.validationErrors);
}

if (
  Array.isArray(data.missingProfileFields) &&
  data.missingProfileFields.length > 0
) {
  reasons.push(
    'Missing candidate profile information: ' +
    data.missingProfileFields.join(', ')
  );
}

if (Array.isArray(data.parserErrors) && data.parserErrors.length > 0) {
  reasons.push(
    'AI response validation issues: ' +
    data.parserErrors.join('; ')
  );
}

if (Array.isArray(data.scoreErrors) && data.scoreErrors.length > 0) {
  reasons.push(
    'Score calculation issues: ' +
    data.scoreErrors.join('; ')
  );
}

if (data.evidenceRequiresManualReview === true) {
  reasons.push(
    'AI evaluation found insufficient evidence for reliable scoring.'
  );
}

if (data.evaluation?.uncertainties?.length > 0) {
  reasons.push(
    'Uncertainties: ' +
    data.evaluation.uncertainties.join('; ')
  );
}

if (reasons.length === 0) {
  reasons.push(
    'The application requires manual verification before matching.'
  );
}

const explanation = [
  'MANUAL REVIEW REQUIRED',
  'A reliable AI match score was not produced.',
  ...reasons,
  'HR action: Verify the application and job information before proceeding.'
].join('\n');

return [
  {
    json: {
      candidateApplicationId: data.candidateApplicationId,
      aiMatchScore: '',
      matchingExplanation: explanation,
      matchingOutcome: 'MANUAL_REVIEW'
    }
  }
];

const response = $input.first().json;
const prepared = $('Prepare Matching Input').first().json;

const applicationId = prepared.candidateApplicationId;
const errors = [];

const criteria = {
  required_skills: ['matched_evidence', 'missing_or_unverified'],
  relevant_experience: ['evidence'],
  education: ['evidence'],
  preferred_skills: ['matched_evidence', 'missing_or_unverified'],
  projects: ['evidence']
};

function getAIContent(data) {
  return (
    data.choices?.[0]?.message?.content ??
    data.body?.choices?.[0]?.message?.content ??
    null
  );
}

function validateCriterion(name, criterion, requiredArrays) {
  if (!criterion || typeof criterion !== 'object' ||
      Array.isArray(criterion)) {
    errors.push(`Missing or invalid criterion: ${name}`);
    return;
  }

  const allowedStatuses = [
    'assessed',
    'insufficient_evidence',
    'not_applicable'
  ];

  if (!allowedStatuses.includes(criterion.evidence_status)) {
    errors.push(`Invalid evidence status: ${name}`);
  }

  if (criterion.evidence_status === 'assessed') {
    if (
      typeof criterion.score !== 'number' ||
      !Number.isFinite(criterion.score) ||
      criterion.score < 0 ||
      criterion.score > 100
    ) {
      errors.push(`Invalid score for ${name}`);
    }
  } else if (criterion.score !== null) {
    errors.push(`Non-assessed criterion must have null score: ${name}`);
  }

  if (typeof criterion.reasoning !== 'string' ||
      criterion.reasoning.trim() === '') {
    errors.push(`Missing reasoning for ${name}`);
  }

  for (const field of requiredArrays) {
    if (
      !Array.isArray(criterion[field]) ||
      !criterion[field].every(item => typeof item === 'string')
    ) {
      errors.push(`Invalid or missing ${field} array in ${name}`);
    }
  }
}

let evaluation = null;

try {
  const content = getAIContent(response);

  if (typeof content !== 'string' || content.trim() === '') {
    throw new Error('AI response content is missing or not text.');
  }

  const cleaned = content
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  evaluation = JSON.parse(cleaned);

  if (
    !evaluation ||
    typeof evaluation !== 'object' ||
    Array.isArray(evaluation)
  ) {
    throw new Error('AI response must be a JSON object.');
  }

  for (const [name, arrays] of Object.entries(criteria)) {
    validateCriterion(name, evaluation[name], arrays);
  }

  if (
    !['sufficient', 'limited', 'insufficient']
      .includes(evaluation.overall_evidence_sufficiency)
  ) {
    errors.push('Invalid overall evidence sufficiency.');
  }

  if (!Array.isArray(evaluation.uncertainties) ||
      !evaluation.uncertainties.every(item => typeof item === 'string')) {
    errors.push('Uncertainties must be an array of strings.');
  }

  if (
    typeof evaluation.summary !== 'string' ||
    evaluation.summary.trim() === ''
  ) {
    errors.push('AI summary is missing or invalid.');
  }

} catch (error) {
  errors.push(`AI response parsing failed: ${error.message}`);
}

const hasInsufficientEvidence =
  evaluation !== null &&
  (
    evaluation.overall_evidence_sufficiency !== 'sufficient' ||
    Object.keys(criteria).some(name =>
      evaluation[name]?.evidence_status === 'insufficient_evidence'
    )
  );

const matchingReady =
  errors.length === 0 &&
  evaluation !== null &&
  !hasInsufficientEvidence;

return [
  {
    json: {
      candidateApplicationId: applicationId,
      matchingReady,
      parserErrors: errors,
      evidenceRequiresManualReview: Boolean(hasInsufficientEvidence),
      evaluation,
      matchingOutcome: matchingReady
        ? 'AI_EVALUATION_VALID'
        : 'MANUAL_REVIEW'
    }
  }
];

const data = $input.first().json;
const evaluation = data.evaluation;

const weights = {
  required_skills: 0.40,
  relevant_experience: 0.20,
  education: 0.15,
  preferred_skills: 0.15,
  projects: 0.10
};

const criteria = Object.keys(weights);
const errors = [];

if (!evaluation || typeof evaluation !== 'object') {
  errors.push('AI evaluation data is missing.');
}

let weightedTotal = 0;
let applicableWeightTotal = 0;

const breakdown = {};

if (evaluation) {
  for (const name of criteria) {
    const criterion = evaluation[name];
    const weight = weights[name];

    if (!criterion || typeof criterion !== 'object') {
      errors.push(`Missing criterion: ${name}`);
      continue;
    }

    const status = criterion.evidence_status;
    const score = criterion.score;

    if (status === 'insufficient_evidence') {
      errors.push(`Insufficient evidence for ${name}.`);
      continue;
    }

    if (status === 'not_applicable') {
      if (score !== null) {
        errors.push(`Not-applicable criterion has a score: ${name}`);
      }

      breakdown[name] = {
        weight,
        score: null,
        weightedContribution: null,
        status
      };

      continue;
    }

    if (status !== 'assessed') {
      errors.push(`Invalid evidence status: ${name}`);
      continue;
    }

    if (
      typeof score !== 'number' ||
      !Number.isFinite(score) ||
      score < 0 ||
      score > 100
    ) {
      errors.push(`Invalid score for ${name}.`);
      continue;
    }

    weightedTotal += score * weight;
    applicableWeightTotal += weight;

    breakdown[name] = {
      weight,
      score,
      weightedContribution: score * weight,
      status
    };
  }
}

if (applicableWeightTotal === 0) {
  errors.push('No applicable criteria are available for scoring.');
}

const matchingReady = errors.length === 0;

const finalScore = matchingReady
  ? Number(
      (weightedTotal / applicableWeightTotal).toFixed(2)
    )
  : null;

return [
  {
    json: {
      candidateApplicationId: data.candidateApplicationId,
      matchingReady,
      scoreErrors: errors,
      aiMatchScore: finalScore,
      scoreBreakdown: breakdown,
      matchingOutcome: matchingReady
        ? 'MATCH_SCORE_CALCULATED'
        : 'MANUAL_REVIEW'
    }
  }
];

const data = $input.first().json;

const evaluation = $('Parse AI Matching Result').first().json.evaluation;

const criteria = [
  ['required_skills', 'Required Skills'],
  ['relevant_experience', 'Relevant Experience'],
  ['education', 'Education'],
  ['preferred_skills', 'Preferred Skills'],
  ['projects', 'Projects']
];

const weights = {
  required_skills: 40,
  relevant_experience: 20,
  education: 15,
  preferred_skills: 15,
  projects: 10
};

const lines = [
  'AI CANDIDATE MATCH ASSESSMENT',
  '',
  `Final Match Score: ${data.aiMatchScore}/100`,
  '',
  'CRITERION BREAKDOWN'
];

for (const [key, label] of criteria) {
  const item = evaluation?.[key];
  const breakdown = data.scoreBreakdown?.[key];

  if (!item || !breakdown) {
    lines.push(`${label}: Assessment information unavailable.`);
    continue;
  }

  if (item.evidence_status === 'not_applicable') {
    lines.push(`${label} (${weights[key]}% weight): Not applicable.`);
    continue;
  }

  lines.push(
    `${label} (${weights[key]}% weight): ${item.score}/100`
  );

  lines.push(
    `Evidence assessment: ${item.reasoning || 'No explanation supplied.'}`
  );
}

if (Array.isArray(evaluation?.uncertainties) &&
    evaluation.uncertainties.length > 0) {
  lines.push(
    '',
    'UNCERTAINTIES',
    ...evaluation.uncertainties.map(item => `- ${item}`)
  );
}

if (evaluation?.summary) {
  lines.push(
    '',
    'AI SUMMARY',
    evaluation.summary
  );
}

lines.push(
  '',
  'IMPORTANT',
  'This score is an advisory assessment based only on the information provided.',
  'It does not represent a hiring decision. HR must independently review the candidate and make all final decisions.'
);

return [
  {
    json: {
      candidateApplicationId: data.candidateApplicationId,
      aiMatchScore: data.aiMatchScore,
      matchingExplanation: lines.join('\n'),
      matchingOutcome: 'MATCH_SCORE_CALCULATED'
    }
  }
];
